/// <reference types="node" />
// Tests of the SQL that drizzle-kit generates from src/data/schema.ts (T027, RF-011 and RF-082):
// the five tables, every column, check, key, index and cascade of the plan's table, read from the
// SQL text, and the SQL run on an in-memory database. The generated files are read at run time.
import Database from "better-sqlite3";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { REAL_MIGRATIONS } from "../scripts/bundle-migrations-fixtures";
import {
  TABLES,
  columnsOf,
  constraintsOf,
  readSql,
  squash,
  squashedTable,
} from "./migration-sql";

const SQL = readSql();

// [table, column, type, "required" | "optional", default ("" when the plan states none)]
const COLUMNS: [string, string, string, "required" | "optional", string][] = [
  ["teams", "id", "integer", "required", ""],
  ["teams", "name", "text", "required", ""],
  ["teams", "category", "text", "optional", ""],
  ["teams", "default_format", "integer", "required", ""],
  ["players", "id", "integer", "required", ""],
  ["players", "team_id", "integer", "required", ""],
  ["players", "name", "text", "required", ""],
  ["players", "number", "text", "required", ""],
  ["players", "is_active", "integer", "required", "(true|1)"],
  ["matches", "id", "integer", "required", ""],
  ["matches", "team_id", "integer", "required", ""],
  ["matches", "format", "integer", "required", ""],
  ["matches", "date", "text", "required", ""],
  ["matches", "time", "text", "optional", ""],
  ["matches", "home_name", "text", "optional", ""],
  ["matches", "away_name", "text", "optional", ""],
  ["matches", "notes", "text", "optional", ""],
  ["matches", "home_score", "integer", "optional", ""],
  ["matches", "away_score", "integer", "optional", ""],
  ["matches", "overtime_count", "integer", "required", "0"],
  ["call_up_entries", "id", "integer", "required", ""],
  ["call_up_entries", "match_id", "integer", "required", ""],
  ["call_up_entries", "player_id", "integer", "required", ""],
  ["call_up_entries", "player_name", "text", "required", ""],
  ["call_up_entries", "player_number", "text", "required", ""],
  ["marks", "call_up_entry_id", "integer", "required", ""],
  ["marks", "column_kind", "text", "required", ""],
  ["marks", "column_number", "integer", "required", ""],
  ["marks", "mark", "text", "required", ""],
];

const CHECKS: [string, string, RegExp][] = [
  [
    "teams",
    "default_format in (4, 6, 8)",
    /check\(+(\w+\.)?default_formatin\(4,6,8\)\)+$/,
  ],
  ["matches", "format in (4, 6, 8)", /check\(+(\w+\.)?formatin\(4,6,8\)\)+$/],
  [
    "marks",
    "column_kind in ('period', 'overtime')",
    /check\(+(\w+\.)?column_kindin\('period','overtime'\)\)+$/,
  ],
  [
    "marks",
    "mark in ('starter', 'sub')",
    /check\(+(\w+\.)?markin\('starter','sub'\)\)+$/,
  ],
];

// [table, foreign key column, referenced table]
const FOREIGN_KEYS: [string, string, string][] = [
  ["players", "team_id", "teams"],
  ["matches", "team_id", "teams"],
  ["call_up_entries", "match_id", "matches"],
  ["call_up_entries", "player_id", "players"],
  ["marks", "call_up_entry_id", "call_up_entries"],
];

const TABLES_WITH_ID = TABLES.filter((table) => table !== "marks");

const INDEXES: [string, string][] = [
  ["matches", "team_id"],
  ["matches", "date,time"],
];

describe("generated migration SQL, tables and columns", () => {
  it("RF-011 RF-082: at least one .sql migration is generated and it creates exactly the five tables", () => {
    const created = [...SQL.matchAll(/CREATE TABLE [`"]?(\w+)[`"]?/gi)].map(
      (match) => match[1],
    );

    expect(created.sort()).toEqual([...TABLES].sort());
  });

  it.each(COLUMNS)(
    "RF-011 RF-082: column %s.%s is of the planned type and nullability",
    (table, column, type, nullability, defaultValue) => {
      const definition = columnsOf(SQL, table).get(column);

      expect(definition).toBeDefined();
      expect(definition).toMatch(new RegExp(`^${type}\\b`));
      if (nullability === "required")
        expect(definition).toMatch(/not null|primary key/);
      else expect(definition).not.toMatch(/not null|primary key/);
      if (defaultValue) {
        expect(definition).toMatch(new RegExp(`default ${defaultValue}\\b`));
      }
    },
  );

  it.each(TABLES_WITH_ID)(
    "RF-011 RF-082: the id of %s is an integer primary key generated by SQLite",
    (table) => {
      expect(columnsOf(SQL, table).get("id")).toMatch(
        /^integer primary key( autoincrement)?\b/,
      );
    },
  );

  it("RF-011 RF-082: the table marks has no id column, only the composite key of the plan", () => {
    const columns = [...columnsOf(SQL, "marks").keys()];

    expect(columns.sort()).toEqual(
      ["call_up_entry_id", "column_kind", "column_number", "mark"].sort(),
    );
    expect(constraintsOf(SQL, "marks")).toContainEqual(
      expect.stringMatching(
        /^primarykey\(call_up_entry_id,column_kind,column_number\)$/,
      ),
    );
  });
});

describe("generated migration SQL, checks, keys, indexes and cascades", () => {
  it.each(CHECKS)(
    "RF-011 RF-082: the table %s checks %s",
    (table, _description, pattern) => {
      expect(constraintsOf(SQL, table).some((item) => pattern.test(item))).toBe(
        true,
      );
    },
  );

  it("RF-011 RF-082: matches checks that both scores are null or both are set", () => {
    const scoreChecks = constraintsOf(SQL, "matches").filter(
      (item) => item.includes("home_score") && item.includes("away_score"),
    );

    expect(scoreChecks.length).toBeGreaterThan(0);
    for (const check of scoreChecks) {
      expect(check).toContain("check(");
      expect(check).toContain("isnull");
      expect(check).toMatch(/isnotnull|\)=\(/);
    }
  });

  it("RF-011 RF-082: call_up_entries has a unique key on (match_id, player_id)", () => {
    const squashed = squash(SQL);
    const asIndex =
      /createuniqueindex[^;]*oncall_up_entries\(match_id,player_id\)/;
    const inTable = constraintsOf(SQL, "call_up_entries").some((item) =>
      /unique\(match_id,player_id\)$/.test(item),
    );

    expect(asIndex.test(squashed) || inTable).toBe(true);
  });

  it.each(INDEXES)(
    "RF-011 RF-082: there is an index on %s (%s)",
    (table, columns) => {
      expect(squash(SQL)).toMatch(
        new RegExp(`createindex[^;]*on${table}\\(${columns}\\)`),
      );
    },
  );

  it.each(FOREIGN_KEYS)(
    "RF-011 RF-082: the foreign key %s.%s to %s deletes with its parent",
    (table, column, parent) => {
      const body = squashedTable(SQL, table);

      expect(body).toMatch(
        new RegExp(
          `(foreignkey\\(${column}\\)|${column}[^,]*?)references${parent}\\(id\\)[^,]*?ondeletecascade`,
        ),
      );
    },
  );

  it("RF-011 RF-082: no foreign key lacks ON DELETE CASCADE, and there are exactly five", () => {
    const squashed = squash(SQL);

    expect(squashed.match(/references/g)).toHaveLength(5);
    expect(squashed.match(/ondeletecascade/g)).toHaveLength(5);
  });
});

describe("generated migration SQL, run on a database", () => {
  it("RF-011 RF-082: every migration runs on an empty in-memory database and leaves the five tables", () => {
    const statements = SQL.split("--> statement-breakpoint");
    const database = new Database(":memory:");

    for (const statement of statements) database.exec(statement);

    const tables = database
      .prepare(
        "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'",
      )
      .all()
      .map((row) => (row as { name: string }).name);
    database.close();
    expect(SQL).not.toBe("");
    expect(tables.sort()).toEqual([...TABLES].sort());
  });

  it("RF-011 RF-082: the journal asks for statement breakpoints and the SQL has one between statements", () => {
    const journal = JSON.parse(
      readFileSync(join(REAL_MIGRATIONS, "meta/_journal.json"), "utf8"),
    ) as { entries: { breakpoints: boolean }[] };

    expect(journal.entries.length).toBeGreaterThan(0);
    expect(journal.entries.every((item) => item.breakpoints)).toBe(true);
    expect(SQL.split("--> statement-breakpoint").length).toBeGreaterThanOrEqual(
      TABLES.length,
    );
  });
});
